mapper.select:
		/*financeUserSetting*/
		SELECT USER_ID
              ,USER_NM
              ,DEFAULTSTOCK            
        FROM  TB_M_USERINFO
        WHERE USER_ID = #{in_userId}

/* selectStockAnalysis */ SELECT * FROM ( SELECT A.* ,ROWNUM AS RNUM FROM ( SELECT TSIS.STOCK_ID, TSIS.STOCK_CODE, (CASE WHEN TSIS.STOCK_MARKET ='kosdaq' THEN '#'||TSIS.STOCK_KO_NAME ELSE TSIS.STOCK_KO_NAME END)AS STOCK_KO_NAME, TSIS.STOCK_MARKET, TSIS.STOCK_URL, '' AS TOTAL_QUANTITY, '' AS TOTAL_PURCHASE_PRICE ,(SELECT STOCK_SMA5 ||',' || STOCK_SMA20 ||','|| STOCK_SMA60 ||','|| STOCK_SMA120 ||','|| STOCK_SMA240 FROM TB_S_STOCK_30MINANALYSIS WHERE STOCK_CODE = TSIS.STOCK_CODE) AS STOCK_30MINSMA ,TSSA.STOCK_SMA5 ||',' || TSSA.STOCK_SMA20 ||','|| TSSA.STOCK_SMA60 ||','|| TSSA.STOCK_SMA120 ||','|| TSSA.STOCK_SMA240 as STOCK_SMA ,(SELECT STOCK_SMA60 FROM TB_S_STOCK_30MINANALYSIS WHERE STOCK_CODE = TSIS.STOCK_CODE) AS STOCK_5BC ,TSSA.STOCK_MON ,TSSA.STOCK_SMA_LINES ,TSSC.SALES_TREND ,TSSC.OP_TREND ,TSSC.EPS_TREND ,TSSA.STOCK_AV_VOLUME ,TSSA.STOCK_AV_VOLUMESIGNAL ,TSSA.STOCK_MACD_TIME ,TO_NUMBER(TSSA.STOCK_MACD_TIMEDAYS) AS STOCK_MACD_TIMEDAYS ,TSSA.STOCK_MACD_SIGNAL ,TSSA.STOCK_MACD_STREAKSIGNAL ,TO_NUMBER(TSSA.STOCK_MACD_STREAKDAYS) AS STOCK_MACD_STREAKDAYS ,TO_NUMBER(TSSA.STOCK_CLOSE) AS STOCK_CLOSE ,(TO_CHAR(TSSA.MODIFY_DATE, (CASE WHEN #{groupMarket}='KR' THEN 'YYYYMMDDHH24' ELSE 'YYYYMMDD' END ))) AS MODIFY_DATE FROM TB_S_STOCK_ANALYSIS TSSA LEFT JOIN TB_S_INTEREST_STOCK TSIS ON TSSA.STOCK_CODE = TSIS.STOCK_CODE LEFT JOIN TB_S_STOCK_CONSENSUS TSSC ON TSSA.STOCK_CODE = TSSC.STOCK_CODE AND TSSC.SALES_TREND !='NULL' WHERE 1=1 AND TSIS.STOCK_TYPE ='stock' AND TSIS.STOCK_COUNTRY_CODE = #{groupMarket} AND TSIS.STOCK_TYPE_SPECS ='CS'
AND TSIS.STOCK_ALIASES = 'snp500'
AND TSIS.STOCK_MARKET = #{STOCK_MARKET}
AND TSSA.USE_DIV ='Y'
AND TSSA.STOCK_MON =#{STATEMONTH}
AND TSSA.STOCK_AV_VOLUMESIGNAL = #{VOLUMESIGNAL}
AND TSSA.STOCK_SMA5 = #{DAY5BC}
AND TSSA.STOCK_SMA60 = #{MONTH5BC}
AND TSSA.STOCK_MACD_SIGNAL = (CASE WHEN 'UP'=#{MACDSIGNAL} THEN 'BUY' ELSE 'DOWN' END)
AND TSSA.STOCK_SMA_LINES =#{STOKCSMALINES}
AND TSSC.SALES_TREND =#{CONSENSUS}
AND TO_NUMBER(TSSA.STOCK_CLOSE) BETWEEN #{RANGE_FROM} AND #{RANGE_TO}
ORDER BY STOCK_SMA DESC, STOCK_30MINSMA DESC, STOCK_MON DESC
)A ) WHERE 1=1 AND RNUM <= 100

	/*selectGroupStockInfo*/
	SELECT STOCK_SEQ
        ,STOCK_CODE
        ,STOCK_GROUP
	FROM TB_S_INTEREST_WATCHLIST
	WHERE STOCK_GROUP = #{group_id}
	AND STOCK_CODE = #{stock_code}
	AND STOCK_GROUP_DIV = #{group_div}

/*selectGroupStockList*/ SELECT TSIS.STOCK_ID, TSIS.STOCK_CODE, (CASE WHEN TSIS.STOCK_MARKET ='kosdaq' THEN '#'||TSIS.STOCK_KO_NAME ELSE TSIS.STOCK_KO_NAME END)AS STOCK_KO_NAME, TSIS.STOCK_MARKET, TSIS.STOCK_URL, TSIW.STOCK_SEQ, TSIW.STOCK_GROUP, SUM(CASE WHEN TRANSACTION_TYPE = 'BUY' THEN QUANTITY WHEN TRANSACTION_TYPE = 'SELL' THEN -QUANTITY ELSE 0 END) AS TOTAL_QUANTITY, SUM(CASE WHEN TRANSACTION_TYPE = 'BUY' THEN (PURCHASE_PRICE * QUANTITY) WHEN TRANSACTION_TYPE = 'SELL' THEN (-PURCHASE_PRICE * QUANTITY) ELSE 0 END) AS TOTAL_PURCHASE_PRICE ,(SELECT STOCK_SMA5 ||',' || STOCK_SMA20 ||','|| STOCK_SMA60 ||','|| STOCK_SMA120 ||','|| STOCK_SMA240 FROM TB_S_STOCK_30MINANALYSIS WHERE STOCK_CODE = TSIS.STOCK_CODE) AS STOCK_30MINSMA ,TSSA.STOCK_SMA5 ||',' || TSSA.STOCK_SMA20 ||','|| TSSA.STOCK_SMA60 ||','|| TSSA.STOCK_SMA120 ||','|| TSSA.STOCK_SMA240 as STOCK_SMA ,(SELECT STOCK_SMA60 FROM TB_S_STOCK_30MINANALYSIS WHERE STOCK_CODE = TSIS.STOCK_CODE) AS STOCK_5BC ,TSSA.STOCK_MON ,TSSA.STOCK_SMA_LINES ,TSSA.STOCK_MACD_TIME ,TSSA.STOCK_MACD_SIGNAL ,TSSA.STOCK_MACD_TIMEDAYS ,TSSA.STOCK_MACD_STREAKSIGNAL ,TSSA.STOCK_MACD_STREAKDAYS ,TSIW.STOCK_CLOSE AS WATCH_CLOSE ,(TO_CHAR(TSIW.CREATE_DATE,'YYYY-MM-DD')) AS WATCH_DATE ,(TO_CHAR(TSSA.MODIFY_DATE,(CASE WHEN #{groupMarket}='KR' THEN 'YYYYMMDDHH24' ELSE 'YYYYMMDD' END ))) AS MODIFY_DATE FROM TB_S_INTEREST_WATCHLIST TSIW LEFT JOIN TB_S_STOCK_PORTFOLIO TSSP ON TSIW.STOCK_CODE = TSSP.STOCK_CODE AND TSSP.CLOSE_FLAG = 'N' LEFT JOIN TB_S_STOCK_ANALYSIS TSSA ON TSSA.STOCK_CODE = TSIW.STOCK_CODE INNER JOIN TB_S_INTEREST_STOCK TSIS ON TSIW.STOCK_CODE = TSIS.STOCK_CODE WHERE 1=1 AND TSIW.STOCK_GROUP = #{group_id} AND TSIW.STOCK_GROUP_DIV = #{group_div} GROUP BY TSIS.STOCK_ID ,TSIS.STOCK_CODE ,TSIS.STOCK_KO_NAME ,TSIS.STOCK_MARKET ,TSIS.STOCK_URL ,TSIW.STOCK_SEQ ,TSIW.STOCK_GROUP ,TSIW.STOCK_CODE ,TSSA.STOCK_MON ,TSSA.STOCK_SMA5 ,TSSA.STOCK_SMA20 ,TSSA.STOCK_SMA60 ,TSSA.STOCK_SMA120 ,TSSA.STOCK_SMA240 ,TSSA.STOCK_CLOSE ,TSSA.STOCK_MACD_TIME ,TSSA.STOCK_MACD_TIMEDAYS ,TSSA.STOCK_MACD_SIGNAL ,TSSA.STOCK_MACD_STREAKSIGNAL ,TSSA.STOCK_MACD_STREAKDAYS ,TSSA.MODIFY_DATE ,TSSA.STOCK_SMA_LINES ,TSIW.STOCK_CLOSE ,TSIW.CREATE_DATE
ORDER BY STOCK_SMA240 ${ANALYSIS},STOCK_SMA120 ${ANALYSIS},STOCK_SMA60 ${ANALYSIS},STOCK_SMA20 ${ANALYSIS},STOCK_SMA5 ${ANALYSIS},STOCK_MACD_SIGNAL,STOCK_MACD_STREAKSIGNAL ${ANALYSIS}, STOCK_MACD_STREAKDAYS
ORDER BY STOCK_SEQ ${SEQ}
ORDER BY TO_NUMBER(TSSA.STOCK_MACD_TIMEDAYS) ${MACDTIMEDAYS}

/*selectPortfolioGroupList*/ SELECT GROUP_ID ,GROUP_NAME ,USE_FLAG ,GROUP_MARKET ,COUNT(TSIW.STOCK_CODE) AS STOCK_COUNT FROM TB_S_INTEREST_GROUP TSIG LEFT JOIN TB_S_INTEREST_WATCHLIST TSIW ON TSIG.GROUP_ID = TSIW.STOCK_GROUP WHERE 1=1 AND USE_FLAG =#{use_flag}
AND GROUP_MARKET =#{groupMarket}
GROUP BY GROUP_ID, GROUP_NAME, USE_FLAG, GROUP_MARKET, GROUP_SEQ ORDER BY GROUP_SEQ

