	/*insertStockPortfolioEvent*/
      INSERT INTO TB_S_STOCK_PORTFOLIO
      (
          STOCK_SEQ
         ,STOCK_GROUP
         ,STOCK_CODE
         ,PURCHASE_PRICE
         ,TARGET_PRICE
         ,QUANTITY
         ,TRANSACTION_TYPE
         ,PRICE_DESCRIPTION
         ,CLOSE_FLAG
         ,CREATE_USER
         ,CREATE_DATE
        )VALUES(
          (SELECT (CASE WHEN COUNT(*) = 0 THEN 1 ELSE  COUNT(*) + 1 END) AS GROUP_SEQ 
          	FROM TB_S_STOCK_PORTFOLIO 
          	WHERE STOCK_GROUP = #{group_id} AND STOCK_CODE =  #{stock_code})
         ,#{group_id}
         ,#{stock_code}
         ,#{start_price}
         ,#{end_price}
         ,#{priceCount}
         ,#{order_div}
         ,#{price_description}
         ,#{close_flag}
         ,#{in_user_id}
         ,SYSDATE
         )

