mapper.insert:
        DECLARE
	    
	    TEMP_OPTIONS_TABLE TABLE (
	        option_id NUMBER,
	        parent_id NUMBER,
	        option_level NUMBER,
	        option_name VARCHAR2(100),
	        option_value CLOB
	    );
	    
	    PROCEDURE InsertOptions(
	        parent_id NUMBER,
	        option_level NUMBER,
	        parent_path VARCHAR2 DEFAULT NULL
	    ) IS
	        CURSOR OptionsCursor IS
	            SELECT option_id, option_name, option_value
	            FROM highcharts_options
	            WHERE parent_id = parent_id
	            AND option_level = option_level;
	
	        option_rec OptionsCursor%ROWTYPE;
	        option_path VARCHAR2(1000);
	    BEGIN
	    
	        FOR option_rec IN OptionsCursor LOOP
	    
	            IF parent_path IS NULL THEN
	                option_path := option_rec.option_name;
	            ELSE
	                option_path := parent_path || '.' || option_rec.option_name;
	            END IF;
	    
	            INSERT INTO TEMP_OPTIONS_TABLE (option_id, parent_id, option_level, option_name, option_value)
	            VALUES (option_rec.option_id, parent_id, option_level, option_path, option_rec.option_value);
	    
	            InsertOptions(option_rec.option_id, option_level + 1, option_path);
	        END LOOP;
	    END InsertOptions;
	
		BEGIN
		
		    InsertOptions(NULL, 1, NULL);
		
		    INSERT INTO highcharts_options (option_id, parent_id, option_level, option_name, option_value)
		    SELECT option_id, parent_id, option_level, option_name, option_value
		    FROM TEMP_OPTIONS_TABLE;
		
		    DROP TABLE TEMP_OPTIONS_TABLE;
		END;
